///that as RpcError.
class ApiError {
    final ApiErrorBody error;

    ApiError({
        required this.error,
    });

    factory ApiError.fromJson(Map<String, dynamic> json) => ApiError(
        error: ApiErrorBody.fromJson(json["error"]),
    );

    Map<String, dynamic> toJson() => {
        "error": error.toJson(),
    };
}

class ApiErrorBody {
    final String code;
    
    ///A human sentence in house copy.
    final String message;

    ApiErrorBody({
        required this.code,
        required this.message,
    });

    factory ApiErrorBody.fromJson(Map<String, dynamic> json) => ApiErrorBody(
        code: json["code"],
        message: json["message"],
    );

    Map<String, dynamic> toJson() => {
        "code": code,
        "message": message,
    };
}

///plinth.ask_answer/1, from the ask edge function (API_CONTRACTS §4.15). Citations or
///silence: every sentence of an answer cites a source; a refusal is templated and carries a
///refusal_code (catalogues/ai_tasks.json).
class AskAnswer {
    final List<AskAction> actions;
    final String? asOfLine;
    final List<ProjectCard> cards;
    final String disclosureLine;
    final AskHandoff handoff;
    final String kind;
    final String? refusalCode;
    final String schema;
    final List<AskSentence> sentences;
    final List<AskSource> sources;
    final String threadId;

    AskAnswer({
        required this.actions,
        required this.asOfLine,
        required this.cards,
        required this.disclosureLine,
        required this.handoff,
        required this.kind,
        required this.refusalCode,
        required this.schema,
        required this.sentences,
        required this.sources,
        required this.threadId,
    });

    factory AskAnswer.fromJson(Map<String, dynamic> json) => AskAnswer(
        actions: List<AskAction>.from(json["actions"].map((x) => AskAction.fromJson(x))),
        asOfLine: json["as_of_line"],
        cards: List<ProjectCard>.from(json["cards"].map((x) => ProjectCard.fromJson(x))),
        disclosureLine: json["disclosure_line"],
        handoff: AskHandoff.fromJson(json["handoff"]),
        kind: json["kind"],
        refusalCode: json["refusal_code"],
        schema: json["schema"],
        sentences: List<AskSentence>.from(json["sentences"].map((x) => AskSentence.fromJson(x))),
        sources: List<AskSource>.from(json["sources"].map((x) => AskSource.fromJson(x))),
        threadId: json["thread_id"],
    );

    Map<String, dynamic> toJson() => {
        "actions": List<dynamic>.from(actions.map((x) => x.toJson())),
        "as_of_line": asOfLine,
        "cards": List<dynamic>.from(cards.map((x) => x.toJson())),
        "disclosure_line": disclosureLine,
        "handoff": handoff.toJson(),
        "kind": kind,
        "refusal_code": refusalCode,
        "schema": schema,
        "sentences": List<dynamic>.from(sentences.map((x) => x.toJson())),
        "sources": List<dynamic>.from(sources.map((x) => x.toJson())),
        "thread_id": threadId,
    };
}

