///plinth.risk_summary/1, served by api.risk_summary(p_slug) (API_CONTRACTS §2). The one
///risk object: web, app, WhatsApp and the risk card render this and nothing else for risk.
class RiskSummary {
    
    ///Null whenever display.state is not scored or bands are not public (DATA_MODEL §12
    ///invariant 8).
    final Band? band;
    final Chip chip;
    
    ///Always count and rate together. Null when not in our records yet.
    final Complaints? complaints;
    
    ///Never part of the band name.
    final Confidence? confidence;
    final DeveloperResponse? developerResponse;
    final Display display;
    
    ///Null when a red-flag rule sets the band, and whenever the band is null.
    final Frequency? frequency;
    final Late12 late12;
    final RiskMeta meta;
    
    ///Public facts that may move the band. Never the proposed band.
    final List<PendingFact> pending;
    final PhaseSummary phase;
    final Price? price;
    final Progress progress;
    
    ///At most 4. Empty unless scored and public.
    final List<Reason> reasons;
    final String schema;
    final RiskShare share;
    final String? whatWouldChange;
    
    ///Facts-only state only.
    final Withheld? withheld;

    RiskSummary({
        required this.band,
        required this.chip,
        required this.complaints,
        required this.confidence,
        required this.developerResponse,
        required this.display,
        required this.frequency,
        required this.late12,
        required this.meta,
        required this.pending,
        required this.phase,
        required this.price,
        required this.progress,
        required this.reasons,
        required this.schema,
        required this.share,
        required this.whatWouldChange,
        required this.withheld,
    });

    factory RiskSummary.fromJson(Map<String, dynamic> json) => RiskSummary(
        band: json["band"] == null ? null : Band.fromJson(json["band"]),
        chip: Chip.fromJson(json["chip"]),
        complaints: json["complaints"] == null ? null : Complaints.fromJson(json["complaints"]),
        confidence: json["confidence"] == null ? null : Confidence.fromJson(json["confidence"]),
        developerResponse: json["developer_response"] == null ? null : DeveloperResponse.fromJson(json["developer_response"]),
        display: Display.fromJson(json["display"]),
        frequency: json["frequency"] == null ? null : Frequency.fromJson(json["frequency"]),
        late12: Late12.fromJson(json["late12"]),
        meta: RiskMeta.fromJson(json["meta"]),
        pending: List<PendingFact>.from(json["pending"].map((x) => PendingFact.fromJson(x))),
        phase: PhaseSummary.fromJson(json["phase"]),
        price: json["price"] == null ? null : Price.fromJson(json["price"]),
        progress: Progress.fromJson(json["progress"]),
        reasons: List<Reason>.from(json["reasons"].map((x) => Reason.fromJson(x))),
        schema: json["schema"],
        share: RiskShare.fromJson(json["share"]),
        whatWouldChange: json["what_would_change"],
        withheld: json["withheld"] == null ? null : Withheld.fromJson(json["withheld"]),
    );

    Map<String, dynamic> toJson() => {
        "band": band?.toJson(),
        "chip": chip.toJson(),
        "complaints": complaints?.toJson(),
        "confidence": confidence?.toJson(),
        "developer_response": developerResponse?.toJson(),
        "display": display.toJson(),
        "frequency": frequency?.toJson(),
        "late12": late12.toJson(),
        "meta": meta.toJson(),
        "pending": List<dynamic>.from(pending.map((x) => x.toJson())),
        "phase": phase.toJson(),
        "price": price?.toJson(),
        "progress": progress.toJson(),
        "reasons": List<dynamic>.from(reasons.map((x) => x.toJson())),
        "schema": schema,
