        hints: json["hints"] == null ? null : List<String>.from(json["hints"]!.map((x) => x)),
        line: json["line"],
    );

    Map<String, dynamic> toJson() => {
        "hints": hints == null ? null : List<dynamic>.from(hints!.map((x) => x)),
        "line": line,
    };
}

