///plinth.who_has_my_number/1, from api.who_has_my_number() (API_CONTRACTS §4.10). Identical
///on web and app. A relay doesn't count toward the cap; family members are not parties.
class WhoHasMyNumber {
    final String countLine;
    final List<EndedParty> ended;
    final String familyLine;
    
    ///Active parties holding the number. At most 3 in any rolling 30 days.
    final List<ContactParty> parties;
    final List<RelayParty> relays;
    final String ruleLine;
    final String schema;

    WhoHasMyNumber({
        required this.countLine,
        required this.ended,
        required this.familyLine,
        required this.parties,
        required this.relays,
        required this.ruleLine,
        required this.schema,
    });

    factory WhoHasMyNumber.fromJson(Map<String, dynamic> json) => WhoHasMyNumber(
        countLine: json["count_line"],
        ended: List<EndedParty>.from(json["ended"].map((x) => EndedParty.fromJson(x))),
        familyLine: json["family_line"],
        parties: List<ContactParty>.from(json["parties"].map((x) => ContactParty.fromJson(x))),
        relays: List<RelayParty>.from(json["relays"].map((x) => RelayParty.fromJson(x))),
        ruleLine: json["rule_line"],
        schema: json["schema"],
    );

    Map<String, dynamic> toJson() => {
        "count_line": countLine,
        "ended": List<dynamic>.from(ended.map((x) => x.toJson())),
        "family_line": familyLine,
        "parties": List<dynamic>.from(parties.map((x) => x.toJson())),
        "relays": List<dynamic>.from(relays.map((x) => x.toJson())),
        "rule_line": ruleLine,
        "schema": schema,
    };
}

